(async function(){'use strict';const initializedInputs=new WeakSet();await customElements.whenDefined('joomla-field-fancy-select');new MutationObserver((mutations)=>{const hasSimpleCategory=mutations.some((mutation)=>[...mutation.addedNodes].some((node)=>(node instanceof Element&&(node.matches('rl-field-simple-category')||node.querySelector('rl-field-simple-category')))));if(hasSimpleCategory){initialize();}}).observe(document.documentElement,{childList:true,subtree:true});if(document.readyState!=='complete'){window.addEventListener('load',initialize,{once:true});return;}
initialize();function initialize(){let pendingInitialization=false;for(const simpleCategory of document.querySelectorAll('rl-field-simple-category')){const fancySelect=simpleCategory.querySelector('joomla-field-fancy-select');if(!fancySelect?.choicesInstance){pendingInitialization=true;continue;}
initializeField(fancySelect.choicesInstance);}
if(pendingInitialization){window.setTimeout(initialize,0);}}
function initializeField(choices){const input=choices.input.element;if(initializedInputs.has(input)){return;}
initializedInputs.add(input);choices.containerInner.element.addEventListener('click',(event)=>{event.stopPropagation();choices.showDropdown();requestAnimationFrame(()=>input.focus());});input.addEventListener('keydown',(event)=>{const category=input.value.trim();if(event.key!=='Enter'||!category.length){return;}
event.preventDefault();event.stopImmediatePropagation();choices.setChoices([{value:category,label:category,selected:true,}],'value','label',false);choices.hideDropdown();});}})();